import assert from "node:assert/strict";
import { test } from "node:test";

import { metadataResolvers } from "./vscode-remote-world.mjs";

test("finds Azure's WireServer among the resolvers Docker hands a container", () => {
  // A Docker-written resolv.conf on an Azure host whose systemd-resolved forwards to WireServer.
  const azure = [
    "# Generated by Docker Engine.",
    "# This file can be edited; Docker Engine will not make further changes once it",
    "# has been modified.",
    "",
    "nameserver 168.63.129.16",
    "search abc.cloudapp.net",
    "",
    "# Based on host file: '/run/systemd/resolve/resolv.conf' (legacy)",
    "# Overrides: []",
  ].join("\n");
  assert.deepEqual(metadataResolvers(azure), ["168.63.129.16"]);
});

test("keeps a machine whose resolvers are not metadata addresses, comments included", () => {
  const office = [
    "# ExtServers: [host(168.63.129.16)]",
    "nameserver 10.0.0.2",
    "nameserver 1.1.1.1",
    "options edns0 trust-ad",
  ].join("\n");
  assert.deepEqual(metadataResolvers(office), []);
});
